function clone(v) { return JSON.parse(JSON.stringify(v)); }
function normalizeCourse(c, source='legacy-import') {
  const course = clone(c||{});
  course.id = String(course.id||uid('course'));
  course.version = String(course.version||'1.0.0');
  course.status = COURSE_STATUSES.includes(course.status) ? course.status : 'published';
  course.role = String(course.role||'all');
  course.modules = Array.isArray(course.modules) ? course.modules.map((m,i)=>normalizeModule(m, i, course)) : [];
  course.moduleCount = course.modules.length;
  course.source = course.source || source;
  course.architectureVersion = 2;
  course.updatedAt = course.updatedAt || now();
  course.createdAt = course.createdAt || course.updatedAt;
  return course;
}
function normalizeModule(m, i, course) {
  const x = clone(m||{});
  x.id = String(x.id||uid('mod'));
  x.courseId = course?.id || x.courseId || '';
  x.order = Number.isFinite(Number(x.order)) ? Number(x.order) : i+1;
  x.minutes = Math.max(1, Number(x.minutes||15));
  x.status = ['draft','published','archived'].includes(String(x.status)) ? String(x.status) : 'published';
  x.assessment = x.assessment || {passingScore:80,questions:[]};
  x.assessment.passingScore = Math.max(0,Math.min(100,Number(x.assessment.passingScore||80)));
  x.lesson = x.lesson || {objective:x.description||'',learn:[],practice:{prompt:'Demonstrate the skill.',evidence:'Record evidence.'},knowledgeCheck:{prompt:'Explain the rule.',passingRule:'Accurate and specific.'}};
  return x;
}

function emptyState() {
  return {
    schemaVersion:SCHEMA_VERSION,
    createdAt:now(),updatedAt:now(),
    courses:LEGACY_IMPORTED_COURSES.map(c=>normalizeCourse(c,'SBC Academy legacy content imported into Training V2')),
    assignments:[],progress:[],attempts:[],certifications:[],reviews:[],events:[],notes:[],sessions:[],
    migration:{legacyV1Imported:false,legacyV9Imported:false},
  };
}

function normalizeState(s) {
  const x=s&&typeof s==='object'?s:emptyState();
  x.schemaVersion=SCHEMA_VERSION;
  for(const k of ['courses','assignments','progress','attempts','certifications','reviews','events','notes','sessions']) if(!Array.isArray(x[k])) x[k]=[];
  x.courses=x.courses.map(c=>normalizeCourse(c,'training-v2'));
  return x;
}

function migrateLegacy(db) {
  const old=db.settings?.trainingSystem;
  const s=emptyState();
  if(old && old.schemaVersion===1) {
    // Preserve the exact old course catalog as historical records rather than deleting it.
    const existingIds=new Set(s.courses.map(c=>c.id));
    for(const c of (old.courses||[])) {
      const imported=normalizeCourse(c,'SBC Training Management V1 historical import');
      if(existingIds.has(imported.id)) imported.id='legacy-'+imported.id;
      imported.status=imported.status==='published'?'archived':imported.status;
      imported.archivedAt=now();
      imported.legacyVersion='V1';
      s.courses.push(imported); existingIds.add(imported.id);
    }
    for(const a of old.assignments||[]) s.assignments.push({...clone(a),id:a.id||uid('asg'),source:'legacy-v1'});
    for(const p of old.progress||[]) s.progress.push({...clone(p),id:p.id||uid('prog'),source:'legacy-v1'});
    for(const a of old.attempts||[]) s.attempts.push({...clone(a),id:a.id||uid('attempt'),source:'legacy-v1'});
    for(const c of old.certifications||[]) s.certifications.push({...clone(c),id:c.id||uid('cert'),source:'legacy-v1'});
    for(const r of old.reviews||[]) s.reviews.push({...clone(r),id:r.id||uid('review'),source:'legacy-v1'});
    for(const e of old.events||[]) s.events.push({...clone(e),id:e.id||uid('evt'),source:'legacy-v1'});
    s.migration.legacyV1Imported=true;
  }
  const legacyV9=db.settings?.v9||{};
  if(legacyV9.trainingProgress && typeof legacyV9.trainingProgress==='object') {
    const core=s.courses.find(c=>c.id==='core-foundations-v2') || s.courses.find(c=>String(c.id).includes('core-foundations'));
    if(core) for(const [userId,record] of Object.entries(legacyV9.trainingProgress)) {
      for(const [moduleId,p] of Object.entries(record?.modules||{})) {
        const mod=core.modules.find(m=>m.legacyId===moduleId||m.id===moduleId); if(!mod) continue;
        if(!s.progress.some(x=>x.userId===userId&&x.courseId===core.id&&x.moduleId===mod.id)) s.progress.push({id:uid('prog'),userId,courseId:core.id,moduleId:mod.id,status:p.status==='completed'?'completed':p.status==='in_progress'?'in_progress':'not_started',score:p.score??null,studySeconds:Number(p.studySeconds||0),startedAt:p.startedAt||null,completedAt:p.completedAt||null,lastActivityAt:p.updatedAt||now(),source:'legacy-v9'});
      }
    }
    s.migration.legacyV9Imported=true;
  }
  return s;
}

function ensureState(db) {
  db.settings=db.settings||{};
  if(db.settings.trainingCenterV2?.schemaVersion===SCHEMA_VERSION) {
    const current=normalizeState(db.settings.trainingCenterV2);
    // V55.8.10 recovery: a prior V2 initialization could persist a valid
    // schemaVersion with an empty course catalog. Do not treat that empty
    // catalog as authoritative; restore the built-in approved SBC curriculum.
    if(current.courses.length===0 && LEGACY_IMPORTED_COURSES.length>0) {
      current.courses=LEGACY_IMPORTED_COURSES.map(c=>normalizeCourse(c,'SBC Academy built-in course catalog recovery'));
      current.recovery=current.recovery||{};
      current.recovery.courseCatalogRestoredAt=now();
      current.recovery.courseCatalogRestoredFrom='V55.8.10';
      db.settings.trainingCenterV2=current;
    }
    return current;
  }
  const migrated=migrateLegacy(db);
  db.settings.trainingCenterV2=migrated;
  return migrated;
}
function saveState(db,state,save) { state.updatedAt=now(); db.settings=db.settings||{}; db.settings.trainingCenterV2=state; return save?save():undefined; }

function isAdmin(user) { return ['owner','manager'].includes(String(user?.role||'')); }
function normalizedTrainingRole(user) {
  const r=String(user?.role||'').trim().toLowerCase().replace(/[ -]+/g,'_');
  const aliases={
    'lead_generator':'lead_researcher',
    'lead_generation':'lead_researcher',
    'researcher':'lead_researcher',
    'prospector':'lead_researcher',
    'business_prospecting_specialist':'lead_researcher',
    'sales_account_manager':'caller',
    'sales_rep':'caller',
    'sales':'caller'
  };
  return aliases[r]||r;
}
function userCanSeeCourse(user,c) {
  if(isAdmin(user)) return true;
  if(c.status!=='published') return false;
  // Core/all-employee courses must remain visible to authenticated employees.
  // Role-specific courses use normalized role aliases so legacy/new employee role labels
  // do not accidentally produce an empty Training Center.
  if(c.role==='all') return user?.active!==false;
  return c.role===normalizedTrainingRole(user);
}
function findCourse(s,id) { return s.courses.find(c=>String(c.id)===String(id)); }
function findModule(s,courseId,moduleId) { const c=findCourse(s,courseId); return c?.modules?.find(m=>String(m.id)===String(moduleId)); }
function assignmentFor(s,userId,courseId) { return s.assignments.find(a=>String(a.userId)===String(userId)&&String(a.courseId)===String(courseId)&&a.status!=='withdrawn'); }
function progressFor(s,userId,courseId,moduleId) { return s.progress.find(p=>String(p.userId)===String(userId)&&String(p.courseId)===String(courseId)&&String(p.moduleId)===String(moduleId)); }
function upsertProgress(s,patch) {
  let p=progressFor(s,patch.userId,patch.courseId,patch.moduleId);
  if(!p) { p={id:uid('prog'),userId:patch.userId,courseId:patch.courseId,moduleId:patch.moduleId,status:'not_started',score:null,studySeconds:0,startedAt:null,completedAt:null,lastActivityAt:null}; s.progress.push(p); }
  Object.assign(p,patch,{lastActivityAt:now()}); return p;
}
function recordEvent(s,event) { s.events.push({id:uid('evt'),at:now(),...event}); if(s.events.length>10000)s.events=s.events.slice(-10000); }
function recordNote(s,note) { s.notes.push({id:uid('note'),createdAt:now(),...note}); if(s.notes.length>5000)s.notes=s.notes.slice(-5000); }

function isLornaUser(user) {
  const name=String(user?.name||'').trim().toLowerCase();
  const username=String(user?.username||'').trim().toLowerCase();
  const email=String(user?.email||user?.profile?.email||'').trim().toLowerCase();
  return username==='lorna' || name==='lorna' || name.startsWith('lorna ') || email==='lornaleona33@gmail.com';
}

function ensureLornaTrainingAccess(db,s) {
  const targets=(db.users||[]).filter(u=>u.active!==false && isLornaUser(u));
  let changed=false;
  for(const u of targets){
    // Lorna must never be left with an empty Training Center because of a stale
    // role label or a previous catalog migration. Restore the approved published
    // employee/Lead Researcher courses and assign them directly to her account.
    const role=normalizedTrainingRole(u);
    for(const desired of buildConsolidatedCatalog()){
      if(desired.status!=='published') continue;
      if(!(desired.role==='all'||desired.role===role)) continue;
      let c=s.courses.find(x=>String(x.id)===String(desired.id));
      if(!c){ c=normalizeCourse(desired,'SBC Academy Lorna access recovery'); s.courses.push(c); changed=true; }
      else if(c.status!=='published' && c.status!=='retired'){ c.status='published'; c.updatedAt=now(); changed=true; }
      if(!assignmentFor(s,u.id,c.id)){
        s.assignments.push({id:uid('asg'),userId:u.id,courseId:c.id,required:true,status:'assigned',assignedAt:now(),assignedBy:'system-lorna-training-recovery',source:'V55.17.8'});
        changed=true;
      }
    }
  }
  return changed;
}

function ensureAssignmentsForWorkforce(db,s) {
  for(const u of (db.users||[]).filter(x=>x.active!==false&&WORKFORCE_ROLES.includes(x.role))) {
    for(const c of s.courses.filter(c=>c.status==='published'&&(c.role==='all'||c.role===normalizedTrainingRole(u)))) {
      if(!assignmentFor(s,u.id,c.id)) s.assignments.push({id:uid('asg'),userId:u.id,courseId:c.id,required:true,status:'assigned',assignedAt:now(),assignedBy:'system'});
    }
  }
}

function moduleStatus(s,userId,courseId,moduleId) { return progressFor(s,userId,courseId,moduleId)?.status||'not_started'; }
function courseSummary(s,userId,course) {
  const mods=course.modules||[], progress=mods.map(m=>progressFor(s,userId,course.id,m.id)).filter(Boolean);
  const completed=progress.filter(p=>['completed','passed'].includes(p.status)).length;
  const passed=progress.filter(p=>p.status==='passed').length;
  const failed=progress.filter(p=>p.status==='failed').length;
  const inProgress=progress.filter(p=>p.status==='in_progress').length;
  const attempts=s.attempts.filter(a=>a.userId===userId&&a.courseId===course.id);
  const lastAttempt=attempts.slice().sort((a,b)=>String(b.submittedAt||'').localeCompare(String(a.submittedAt||'')))[0]||null;
  return {courseId:course.id,title:course.title,version:course.version,status:course.status,moduleCount:mods.length,completed,passed,failed,inProgress,percent:mods.length?Math.round(completed/mods.length*100):0,attempts:attempts.length,lastAttempt,modules:mods.map(m=>({...m,status:moduleStatus(s,userId,course.id,m.id),attempts:attempts.filter(a=>a.moduleId===m.id).length}))};
}
function summarizeUser(db,s,userId) {
  const user=(db.users||[]).find(u=>String(u.id)===String(userId));
  const assigned=s.assignments.filter(a=>String(a.userId)===String(userId)&&a.status!=='withdrawn');
  const courseIds=new Set(assigned.map(a=>a.courseId));
  const published=s.courses.filter(c=>c.status==='published'&&(c.role==='all'||c.role===normalizedTrainingRole(user)));
  published.forEach(c=>courseIds.add(c.id));
  const courses=[...courseIds].map(id=>findCourse(s,id)).filter(Boolean).map(c=>courseSummary(s,userId,c));
  const allProgress=s.progress.filter(p=>String(p.userId)===String(userId));
  const attempts=s.attempts.filter(a=>String(a.userId)===String(userId));
  const certs=s.certifications.filter(c=>String(c.userId)===String(userId));
  const requiredModules=courses.reduce((n,c)=>n+c.moduleCount,0);
  const completed=courses.reduce((n,c)=>n+c.completed,0);
  return {userId,name:user?.name||'',username:user?.username||'',role:user?.role||'',active:user?.active!==false,assignedCourses:assigned.length,visibleCourses:courses.length,requiredModules,completedModules:completed,percent:requiredModules?Math.round(completed/requiredModules*100):0,passed:allProgress.filter(x=>x.status==='passed').length,failed:allProgress.filter(x=>x.status==='failed').length,retraining:allProgress.filter(x=>x.status==='retraining_required').length,inProgress:allProgress.filter(x=>x.status==='in_progress').length,attempts:attempts.length,certifications:certs,courses};
}

function getForUser(db,user) {
  const s=ensureState(db); ensureAssignmentsForWorkforce(db,s); ensureLornaTrainingAccess(db,s);
  const assignments=s.assignments.filter(a=>String(a.userId)===String(user.id)&&a.status!=='withdrawn').map(a=>{const c=findCourse(s,a.courseId);return c?{assignment:a,course:c,summary:courseSummary(s,user.id,c)}:null}).filter(Boolean);
  const available=s.courses.filter(c=>userCanSeeCourse(user,c)&&!assignments.some(x=>x.course.id===c.id));
  return {version:VERSION,user:{id:user.id,name:user.name,role:user.role},assigned:assignments,available,progress:s.progress.filter(p=>String(p.userId)===String(user.id)),attempts:s.attempts.filter(a=>String(a.userId)===String(user.id)),certifications:s.certifications.filter(c=>String(c.userId)===String(user.id)),history:s.events.filter(e=>String(e.userId)===String(user.id)).slice(-500).reverse(),notes:s.notes.filter(n=>String(n.userId)===String(user.id)).slice(-100).reverse()};
}

function overview(db,s,opts={}) {
  const includeArchived=opts.includeArchived!==false;
  const courses=s.courses.filter(c=>includeArchived||!['archived','retired'].includes(c.status));
  const employees=(db.users||[]).filter(u=>u.role!=='owner').map(u=>summarizeUser(db,s,u.id));
  return {version:VERSION,schemaVersion:SCHEMA_VERSION,filters:{includeArchived},courses:courses.map(c=>({id:c.id,title:c.title,version:c.version,role:c.role,status:c.status,moduleCount:c.modules?.length||0,createdAt:c.createdAt,updatedAt:c.updatedAt,source:c.source,legacyVersion:c.legacyVersion||null})),employees,recentEvents:s.events.slice(-250).reverse(),recentAttempts:s.attempts.slice(-250).reverse(),recentReviews:s.reviews.slice(-250).reverse(),certifications:s.certifications.slice(-250).reverse()};
}

function history(db,s,userId) {
  return {user:(db.users||[]).find(u=>String(u.id)===String(userId))||null,summary:summarizeUser(db,s,userId),progress:s.progress.filter(x=>String(x.userId)===String(userId)),attempts:s.attempts.filter(x=>String(x.userId)===String(userId)).sort((a,b)=>String(b.submittedAt||'').localeCompare(String(a.submittedAt||''))),reviews:s.reviews.filter(x=>String(x.userId)===String(userId)).sort((a,b)=>String(b.reviewedAt||'').localeCompare(String(a.reviewedAt||''))),certifications:s.certifications.filter(x=>String(x.userId)===String(userId)),events:s.events.filter(x=>String(x.userId)===String(userId)).slice(-1000).reverse(),notes:s.notes.filter(x=>String(x.userId)===String(userId)).slice(-500).reverse()};
}

// Request-scoped controller. Unlike the supplied Map-based example, this never stores
// student state in process memory. It records durable state through the caller's db object.
class TrainingSessionController {
  constructor(db,save) { this.db=db; this.save=save; }
  start(userId,courseId,moduleId) {
    const s=ensureState(this.db),c=findCourse(s,courseId),m=findModule(s,courseId,moduleId); if(!c||!m) throw new Error('Training course or module does not exist.');
    const p=upsertProgress(s,{userId,courseId,moduleId,status:'in_progress',startedAt:progressFor(s,userId,courseId,moduleId)?.startedAt||now()});
    recordEvent(s,{type:'lesson_started',userId,courseId,moduleId}); saveState(this.db,s,this.save); return p;
  }
  complete(userId,courseId,moduleId,evidence='') {
    const s=ensureState(this.db),c=findCourse(s,courseId),m=findModule(s,courseId,moduleId); if(!c||!m) throw new Error('Training course or module does not exist.');
    const p=upsertProgress(s,{userId,courseId,moduleId,status:'completed',completedAt:now(),evidence:String(evidence).slice(0,5000)});
    recordEvent(s,{type:'lesson_completed',userId,courseId,moduleId}); saveState(this.db,s,this.save); return p;
  }
  submitAttempt(userId,courseId,moduleId,payload={}) {
    const s=ensureState(this.db),c=findCourse(s,courseId),m=findModule(s,courseId,moduleId); if(!c||!m) throw new Error('Training course or module does not exist.');
    const attempt={id:uid('attempt'),userId,courseId,moduleId,type:String(payload.type||'knowledge_check'),answers:Array.isArray(payload.answers)?payload.answers.slice(0,100):[],response:String(payload.response||'').slice(0,12000),score:payload.score==null?null:Math.max(0,Math.min(100,Number(payload.score))),passed:payload.passed==null?null:Boolean(payload.passed),status:'submitted',submittedAt:now(),reviewedAt:null,reviewedBy:null,reviewNotes:''};
    s.attempts.push(attempt); recordEvent(s,{type:'assessment_submitted',userId,courseId,moduleId,attemptId:attempt.id}); saveState(this.db,s,this.save); return attempt;
  }
}

function createCourse(db,save,actor,b={}) {
  const s=ensureState(db),c={id:uid('course'),title:String(b.title||'New Training').trim().slice(0,200),role:String(b.role||'all'),version:String(b.version||'1.0.0'),status:'draft',description:String(b.description||'').slice(0,3000),modules:[],createdAt:now(),updatedAt:now(),createdBy:actor.id,source:'SBC Training Center'};
  s.courses.push(c);recordEvent(s,{type:'course_created',courseId:c.id,actorId:actor.id});saveState(db,s,save);return c;
}
function addModule(db,save,actor,courseId,b={}) {
  const s=ensureState(db),c=findCourse(s,courseId);if(!c)throw new Error('Course not found.');
  const m=normalizeModule({id:uid('mod'),title:String(b.title||'New Module').trim().slice(0,200),role:String(b.role||c.role||'all'),minutes:Number(b.minutes||15),description:String(b.description||'').slice(0,4000),lesson:b.lesson||{objective:String(b.description||''),learn:[],practice:{prompt:'Demonstrate the skill.',evidence:'Record evidence.'},knowledgeCheck:{prompt:'Explain the rule.',passingRule:'Accurate and specific.'}},assessment:b.assessment||{passingScore:80,questions:[]},status:'draft'},c.modules.length,c);
  c.modules.push(m);c.moduleCount=c.modules.length;c.updatedAt=now();recordEvent(s,{type:'module_created',courseId:c.id,moduleId:m.id,actorId:actor.id});saveState(db,s,save);return m;
}
function patchCourse(db,save,actor,courseId,b={}) {
  const s=ensureState(db),c=findCourse(s,courseId);if(!c)throw new Error('Course not found.');
  for(const k of ['title','role','version','description']) if(b[k]!==undefined)c[k]=String(b[k]);
  if(b.status!==undefined && COURSE_STATUSES.includes(String(b.status))) c.status=String(b.status);
  if(c.status==='archived'||c.status==='retired') c.archivedAt=c.archivedAt||now();
  if(c.status==='published') c.publishedAt=c.publishedAt||now();
  c.updatedAt=now();recordEvent(s,{type:'course_updated',courseId:c.id,status:c.status,actorId:actor.id});saveState(db,s,save);return c;
}
function assignCourse(db,save,actor,userId,courseId,required=true) {
  const s=ensureState(db),c=findCourse(s,courseId),u=(db.users||[]).find(x=>String(x.id)===String(userId));if(!u||!c)throw new Error('Employee or course not found.');
  let a=assignmentFor(s,u.id,c.id);if(!a){a={id:uid('asg'),userId:u.id,courseId:c.id,required:Boolean(required),status:'assigned',assignedAt:now(),assignedBy:actor.id};s.assignments.push(a);}else{a.status='assigned';a.required=Boolean(required);a.updatedAt=now();a.withdrawnAt=null;}
  recordEvent(s,{type:'assignment',userId:u.id,courseId:c.id,actorId:actor.id,status:a.status});saveState(db,s,save);return a;
}
function reviewAttempt(db,save,actor,attemptId,score,passed,notes='') {
  const s=ensureState(db),a=s.attempts.find(x=>String(x.id)===String(attemptId));if(!a)throw new Error('Assessment attempt not found.');
  const pct=Math.max(0,Math.min(100,Number(score||0)));const ok=Boolean(passed??(pct>=80));a.score=pct;a.passed=ok;a.status=ok?'passed':'failed';a.reviewedAt=now();a.reviewedBy=actor.id;a.reviewNotes=String(notes||'').slice(0,5000);
  const p=upsertProgress(s,{userId:a.userId,courseId:a.courseId,moduleId:a.moduleId,status:ok?'passed':'retraining_required',score:pct});
  s.reviews.push({id:uid('review'),userId:a.userId,attemptId:a.id,status:ok?'Passed':'Failed',score:pct,notes:a.reviewNotes,reviewedAt:now(),reviewedBy:actor.id});
  recordEvent(s,{type:'assessment_reviewed',userId:a.userId,courseId:a.courseId,moduleId:a.moduleId,attemptId:a.id,score:pct,passed:ok,actorId:actor.id});saveState(db,s,save);return {attempt:a,progress:p};
}
function certify(db,save,actor,userId,b={}) {
  const s=ensureState(db),u=(db.users||[]).find(x=>String(x.id)===String(userId));if(!u)throw new Error('Employee not found.');
  const status=CERT_STATUSES.includes(String(b.status))?String(b.status):'Not Certified';
  const c={id:uid('cert'),userId:String(userId),status,courseId:String(b.courseId||'all'),certifiedAt:status==='Certified'?now():null,certifiedBy:status==='Certified'?actor.id:null,expiresAt:String(b.expiresAt||''),reason:String(b.reason||'').slice(0,4000),updatedAt:now()};
  s.certifications.push(c);recordEvent(s,{type:'certification',userId:String(userId),status,actorId:actor.id,certificationId:c.id});saveState(db,s,save);return c;
}
function dashboard(db,s) {
  const active=(db.users||[]).filter(u=>u.active!==false&&u.role!=='owner');
  const summaries=active.map(u=>summarizeUser(db,s,u.id));
  const totalAttempts=s.attempts.length,passed=s.attempts.filter(a=>a.passed===true).length,failed=s.attempts.filter(a=>a.passed===false).length;
  return {employees:summaries,metrics:{courses:s.courses.length,published:s.courses.filter(c=>c.status==='published').length,archived:s.courses.filter(c=>c.status==='archived').length,retired:s.courses.filter(c=>c.status==='retired').length,draft:s.courses.filter(c=>c.status==='draft').length,employees:active.length,attempts:totalAttempts,passedAttempts:passed,failedAttempts:failed,passRate:totalAttempts?Math.round(passed/totalAttempts*100):0,retraining:s.progress.filter(p=>p.status==='retraining_required').length},recentEvents:s.events.slice(-100).reverse(),recentAttempts:s.attempts.slice(-100).reverse(),recentCertifications:s.certifications.slice(-100).reverse()};
}

function cloneCourseVersion(db,save,actor,courseId,version){
  const s=ensureState(db),source=findCourse(s,courseId); if(!source) throw new Error('Course not found.');
  const c=clone(source); c.id=uid('course'); c.version=String(version||'').trim()||'1.0.0'; c.status='draft'; c.createdAt=now(); c.updatedAt=now(); c.createdBy=actor.id; c.source=`Versioned copy of ${source.id}`; c.archivedAt=null; c.publishedAt=null; c.modules=(c.modules||[]).map((m,i)=>{const x=clone(m);x.id=uid('mod');x.courseId=c.id;x.status='draft';x.order=i+1;return x;}); c.moduleCount=c.modules.length; s.courses.push(c); recordEvent(s,{type:'course_version_created',courseId:c.id,sourceCourseId:source.id,version:c.version,actorId:actor.id}); saveState(db,s,save); return c; }


const CURRICULUM_VERSION='2026.1';
const CORE_PHASES={
  'core-v15-01':'FOUNDATIONS','core-v15-02':'FOUNDATIONS','core-v15-03':'FOUNDATIONS','core-v15-04':'FOUNDATIONS','core-v15-05':'FOUNDATIONS','core-v15-06':'FOUNDATIONS',
  'core-v15-07':'LEAD RESEARCH','core-v15-08':'LEAD RESEARCH','core-v15-09':'LEAD RESEARCH','core-v15-10':'LEAD RESEARCH','core-v15-11':'LEAD RESEARCH','core-v15-12':'LEAD RESEARCH',
  'core-v15-13':'SALES & CALL CENTER','core-v15-14':'SALES & CALL CENTER','core-v15-15':'SALES & CALL CENTER','core-v15-16':'SALES & CALL CENTER','core-v15-17':'SALES & CALL CENTER','core-v15-18':'SALES & CALL CENTER','core-v15-19':'SALES & CALL CENTER',
  'core-v15-20':'FULFILLMENT','core-v15-21':'FULFILLMENT','core-v15-22':'FULFILLMENT','core-v15-23':'FULFILLMENT',
  'core-v15-24':'CERTIFICATION','core-v15-25':'CUSTOMER EXPERIENCE','core-v15-26':'CUSTOMER EXPERIENCE','core-v15-27':'CUSTOMER EXPERIENCE','core-v15-28':'CUSTOMER EXPERIENCE',
  'core-v15-29':'SALES & CALL CENTER','core-v15-30':'SALES & CALL CENTER','core-v15-31':'FULFILLMENT','core-v15-32':'CERTIFICATION','core-v15-33':'OPERATIONS','core-v15-34':'FULFILLMENT','core-v15-35':'OPERATIONS'
};

function enrichCurriculumCourse(course,index){
  const c=clone(course);
  c.curriculumVersion=CURRICULUM_VERSION;
  c.recommendedOrder=index+1;
  c.estimatedMinutes=(c.modules||[]).reduce((n,m)=>n+Math.max(1,Number(m.minutes||15)),0);
  c.completionStandard='Complete every required module, submit the knowledge checks, demonstrate the skill in practice, and meet the module passing standard before certification.';
  if(c.id==='core-foundations-v2'){
    c.path='CORE → RESEARCH → SALES → FULFILLMENT → CUSTOMER EXPERIENCE → OPERATIONS → CERTIFICATION';
    c.prerequisites=[];
    c.certification='SBC Core Production Ready';
    c.description='The complete SBC Academy foundation. Builds the common operating language, lead research, sales, fulfillment, customer experience, Command Center workflows, demo tools and production-readiness skills.';
    c.modules=(c.modules||[]).map((m,i)=>({...m,phase:CORE_PHASES[m.id]||m.phase||'CORE',order:i+1}));
  } else if(c.id==='big3-operations-v1'){
    c.path='SYSTEM OPERATING MODEL';
    c.prerequisites=['core-foundations-v2'];
    c.certification='SBC Big 3 Operations Ready';
  } else {
    c.prerequisites=['core-foundations-v2'];
    c.certification=(c.role||'all')==='manager'?'SBC Manager Production Ready':
      (c.role||'all')==='caller'?'SBC Caller Production Ready':
      (c.role||'all')==='lead_researcher'?'SBC Lead Researcher Production Ready':
      (c.role||'all')==='fulfillment'?'SBC Fulfillment Production Ready':'SBC Production Ready';
  }
  c.source='SBC Academy consolidated curriculum 2026.1 — V15 legacy content + production role tracks + Big 3 operating system';
  return c;
}

function buildConsolidatedCatalog(){
  return LEGACY_IMPORTED_COURSES.map((c,i)=>enrichCurriculumCourse(c,i));
}

function repairCourseCatalog(db){
  db.settings=db.settings||{};
  const s=ensureState(db);
  const catalog=buildConsolidatedCatalog();
  let changed=false;
  if(!Array.isArray(s.courses)) s.courses=[];
  for(const desired of catalog){
    let current=s.courses.find(c=>String(c.id)===String(desired.id));
    if(!current){
      s.courses.push(normalizeCourse(desired,'SBC Academy consolidated catalog recovery'));
      changed=true;
      continue;
    }
    // Non-destructive curriculum merge: preserve status, timestamps and progress,
    // while adding missing modules/metadata from the consolidated catalog.
    const existingModuleIds=new Set((current.modules||[]).map(m=>String(m.id)));
    for(const dm of desired.modules||[]){
      if(!existingModuleIds.has(String(dm.id))){
        current.modules=current.modules||[];
        current.modules.push(normalizeModule(dm,current.modules.length,current));
        changed=true;
      }
    }
    const metadataKeys=['curriculumVersion','recommendedOrder','estimatedMinutes','completionStandard','path','prerequisites','certification'];
    for(const key of metadataKeys){
      if(JSON.stringify(current[key])!==JSON.stringify(desired[key])){
        current[key]=clone(desired[key]);
        changed=true;
      }
    }
    if(current.id==='core-foundations-v2'){
      const byId=new Map((current.modules||[]).map(m=>[String(m.id),m]));
      for(const dm of desired.modules||[]){
        const cm=byId.get(String(dm.id));
        if(cm && cm.phase!==dm.phase){cm.phase=dm.phase;changed=true;}
        if(cm && Number(cm.order)!==Number(dm.order)){cm.order=dm.order;changed=true;}
      }
    }
    current.moduleCount=(current.modules||[]).length;
  }
  if(changed){
    s.recovery=s.recovery||{};
    s.recovery.curriculumVersion=CURRICULUM_VERSION;
    s.recovery.courseCatalogConsolidatedAt=now();
    s.recovery.courseCatalogConsolidatedFrom='V55.8.14';
    s.updatedAt=now();
  }
  return {state:s,changed};
}

